import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 13 — Data & Access Rules","description":"","frontmatter":{"source":"weeks/13-data-and-access/README.md"},"headers":[],"relativePath":"weeks/13-data-and-access/index.md","filePath":"weeks/13-data-and-access/index.md"}'),s={name:"weeks/13-data-and-access/index.md"};function n(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-13--data--access-rules" tabindex="-1">Week 13 — Data &amp; Access Rules <a class="header-anchor" href="#week-13--data--access-rules" aria-label="Permalink to &quot;Week 13 — Data &amp; Access Rules&quot;">​</a></h1><blockquote><p>A public key plus missing access rules equals a public database. This week you make that mistake on purpose, fix it, then connect your capstone to a database the safe way.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min at most)</td><td>Read this page, create a Supabase account and an empty practice project, read case 12 (UpGuard). See <a href="#before-class">Before class</a></td></tr><tr><td><strong>Studio A</strong></td><td>Talk: who you are versus what you may do, keys, grants, row-level security, this year&#39;s leaks · live attack demo · the <strong>RLS Attack Lab</strong> on the hosted attack page · checkpoint share</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell · connect your capstone to Supabase (worked example) and attack your own table · connect one feature with the agent · exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong></td><td>Default 11:59 pm the night before. Your <strong>second feature type</strong> working at the production URL, merged through a pull request · section 3 of <code>SECURITY_CHECKLIST.md</code> with evidence · <code>PROMPTS.md</code> teach-backs · reflection on Canvas</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: explaining errors and SQL, building the data feature with the agent (approvals on) · 🟡 AI limited: <code>supabase/policies.sql</code> (you decide who may do what and can explain every line; the AI may explain and critique) · 🔴 AI off: your &quot;who may do what&quot; table, the reflection, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>README (this page), <a href="./lab.html">Week 13 lab — Attack, fix, connect</a>, <a href="./homework.html">Week 13 homework — Persist it, and prove who can reach it</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a> · the capstone starter&#39;s <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a> · <a href="./../../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST.md template</a> · <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab" target="_blank" rel="noreferrer">RLS Attack Lab kit</a> · <a href="./../../resources/glossary.html">Glossary</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your second feature type works at least roughly at the production URL, and any table it uses has RLS on, explicit grants and policies in <code>supabase/policies.sql</code>. Week 14 sweeps and reviews it</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h: prep 30 min, homework about 5.5 h</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system. Graded personal writing (your reflection) goes there, never in a repo.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain the difference between <strong>authentication</strong> (who you are) and <strong>authorization</strong> (what you are allowed to do), and say why authorization must be enforced on the server or in the database, never only in the page.</li><li>Explain why a Supabase <strong>publishable key</strong> is safe in the browser <strong>only</strong> when <strong>row-level security (RLS)</strong> is on, and why a <strong>secret key</strong> never goes in the browser.</li><li>Put a practice table in a vulnerable state, attack it with only its public key, then write RLS policies until your own attack fails.</li><li>Tell the three kinds of &quot;blocked&quot; apart: no grant, refused by a policy, and 0 rows.</li><li>Connect your capstone to Supabase with explicit <strong>grants</strong> and RLS policies in <code>supabase/policies.sql</code>, and prove with an attack that they hold.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><p>Before Studio A (30 minutes at most):</p><ul><li>☐ Read this page.</li><li>☐ Create a free Supabase account and a new, empty project called <code>rls-lab</code> on the free plan (<a href="./../../TOOLS.html">Tool Handout</a>), with any region and a database password you won&#39;t need again. It takes a minute or two to set up, so doing it now saves lab time.</li><li>☐ Read <a href="./../../resources/case-studies.html#12-upguard-16326-exposed-supabase-databases">case 12: UpGuard&#39;s 16,326 exposed Supabase databases</a>.</li><li>☐ Check Milestone 1: your capstone is deployed and your week-12 features went through <strong>pull requests</strong>. Behind? Tell your instructor: Studio A works without a finished capstone.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-13.html" target="_blank" rel="noreferrer">slides</a>) · live attack demo · <a href="./lab.html#studio-a--attack-and-fix-75-min">RLS Attack Lab</a> on the hosted attack page · checkpoint share: your before/after table</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · <a href="./lab.html#studio-b--connect-your-capstone-75-min">connect your capstone to Supabase</a>, then attack your own table · connect one feature with the agent · exit ticket</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-13.html" target="_blank" rel="noreferrer">Slides</a> and <a href="./lab.html">lab</a>, with Core and If time parts</li><li><a href="./homework.html">Homework</a>: your second feature type, and the database part of your security checklist</li><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/tools/rls-attack.html" target="_blank" rel="noreferrer">RLS attack page</a>: the hosted tester (nothing to install)</li><li><a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab" target="_blank" rel="noreferrer">RLS Attack Lab kit</a>: <code>setup.sql</code>, <code>fix.sql</code>, the tester page&#39;s source, and the per-user stretch</li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p><strong>Authentication vs authorization.</strong> <a href="./../../resources/glossary.html#authentication">Authentication</a> answers &quot;who are you?&quot; (signing in). <a href="./../../resources/glossary.html#authorization">Authorization</a> answers &quot;what are you allowed to see and do?&quot; A signed-in user is still not allowed to read <em>everyone&#39;s</em> private notes. Karpathy&#39;s own example: an agent matched two accounts by email address instead of a stable user ID, a bug only an understanding human caught (<a href="./../../research/landscape-report-2026-09.html">September report</a>).</p><p><strong>Authorization must live on the server or in the database.</strong> Anything in the browser is public: a user can open DevTools, read your JavaScript and call your database directly. Hiding a button stops no one.</p><p><strong>Supabase in one line.</strong> A <a href="./../../resources/glossary.html#postgres">Postgres</a> database plus an automatic web API (the <strong>Data API</strong>), so your page can talk to the database directly with a key.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Not every key is a secret.</strong> The Supabase <a href="./../../resources/glossary.html#publishable-key">publishable key</a> (starts <code>sb_publishable_</code>) and your project URL are public by design: they go in <code>public/config.js</code>, and anyone who loads your site can read them. That&#39;s safe <strong>only</strong> when RLS is on with the right policies. The <a href="./../../resources/glossary.html#secret-key-service-role-key">secret key</a> (starts <code>sb_secret_</code>) skips every access rule, so it lives only in server environment variables, never in <code>public/</code>, a repo or a chat. Your LLM key from week 9 is a secret too. Older projects also show legacy <code>anon</code> and <code>service_role</code> keys (long strings starting <code>eyJ</code>); they are deprecated, so use the new ones.</p></div><p><strong>Two locks on every table.</strong> A <a href="./../../resources/glossary.html#grant">grant</a> decides whether a role, such as <code>anon</code> (anyone with the publishable key), may use a table at all. An RLS <a href="./../../resources/glossary.html#policy">policy</a> decides which rows that role may read or change. From 30 October 2026, new Supabase tables get no grants automatically, so the API answers &quot;permission denied&quot; until you add them (<a href="https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically" target="_blank" rel="noreferrer">Supabase changelog</a>). Always add grants <strong>and</strong> turn on RLS with policies together, in one file. Never &quot;fix&quot; a permission-denied error with a bare grant to <code>anon</code>: that rebuilds exactly the leak below.</p><p><strong>RLS in plain words.</strong> <a href="./../../resources/glossary.html#row-level-security-rls">Row-level security</a> is a switch on each table. <strong>Off:</strong> anyone with a grant can read and write every row. <strong>On, with no policies:</strong> nobody using the public key gets anything. <strong>On, with policies:</strong> each request is allowed only if a policy says so, for example &quot;anyone may read rows where <code>is_public</code> is true&quot;.</p><p><strong>If you know Python or SQL:</strong> a policy&#39;s <code>using (...)</code> part works like a <code>WHERE</code> clause added to every query, so rows that fail it are invisible. Its <code>with check (...)</code> part works like an <code>assert</code> on every new or changed row. That&#39;s why a blocked update returns &quot;0 rows&quot; with no error, while a blocked insert raises one. So <strong>always check how many rows changed</strong>, not only whether there was an error.</p><p><strong>This year&#39;s leaks.</strong> In September 2026 UpGuard found <strong>16,326 Supabase databases with publicly readable tables</strong>; tables that agents create through the API start with RLS off (<a href="https://www.upguard.com/blog/everything-everywhere-systemic-data-exposure-in-supabase-apps" target="_blank" rel="noreferrer">UpGuard</a>). Platforms fail too: a missing ownership check in Lovable&#39;s project API let any free account read other users&#39; code and database credentials (<a href="https://dev.to/alejandxr/lovable-bola-48-days-five-api-calls-source-code-database-credentials-of-other-peoples-projects-4ai0" target="_blank" rel="noreferrer">Sable</a>). Full write-ups, including the 2025 cases (Lovable&#39;s missing policies, Moltbook, Base44): <a href="./../../resources/case-studies.html">Case Studies</a>. Week 14 covers the rest of the map: cross-site scripting, secrets in old commits, packages and prompt injection.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>Complete the week 13 exit ticket at the end of Studio B, with AI off (🔴). You&#39;ll explain authentication versus authorization, say exactly where authorization is enforced in your app, say when a public key becomes a problem, and answer one question from memory about your first agent-built feature from week 11. Exit tickets are graded on completion, not correctness.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p><a href="./homework.html">Homework</a>: your second feature type through a pull request, section 3 of your checklist, <code>PROMPTS.md</code> and your reflection. About 5.5 hours.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Supabase is down or won&#39;t create a project:</strong> follow the instructor&#39;s live demo and fill in the before/after table from it, then use <strong>Neon or Turso</strong> (database only, no sign-in; see <a href="./../../TOOLS.html">Tool Handout</a>), or keep data in the browser with <code>localStorage</code> for now. The <em>idea</em> (client vs server, authorization rules) is assessed, not the vendor. More: <a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>.</li><li><strong>&quot;Permission denied for table …&quot;:</strong> the table has no grant yet. Add the grant <strong>and</strong> RLS and policies together (lab Part B1), never a grant on its own.</li><li><strong>Supabase project paused:</strong> free projects pause after about a week without activity. Open the dashboard and restore it; your data comes back.</li><li><strong>The hosted attack page won&#39;t load:</strong> open <code>attack.html</code> from the <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab" target="_blank" rel="noreferrer">RLS Attack Lab kit</a> on your own computer, or serve the kit folder in a Codespace with <code>python3 -m http.server 8000</code>.</li><li><strong>Codespaces quota or Copilot credits gone:</strong> the attack page runs in any browser; edit your capstone in github.dev; write the agent step by hand from the starter&#39;s feature pattern (<a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>).</li><li><strong>Your capstone is behind:</strong> do the RLS lab, and the worked example on a practice branch. Persistence becomes your homework priority; book office hours early in the week.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Add Supabase Auth so each user sees only their own rows, or attack your own live site from the DevTools Console (both in the lab&#39;s Part B3).</li><li>Read case 16 in <a href="./../../resources/case-studies.html">Case Studies</a> (Lovable&#39;s missing ownership check) and write down which RLS policy would have answered &quot;is this row yours?&quot;.</li></ul>',32)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
